INSERT INTO tbl_native (serial_no, native_name, gender, gender_code, birth_at, birth_date, birth_date_text, birth_date_legacy, birth_time_legacy, birth_time, birth_time_text, place_id, birth_place, country_name, address_text, remarks, life_spheres, temp_record, is_temporary) VALUES (1169,'MANDEEP KAUR','F','F',NULL,NULL,'15.04.1992','15.04.1992','02.25','02:25:00','02.25',NULL,'SANGRUR','INDIA','C/O GURPREET SINGH PADOSI KE DOST KI WIFE, HUSBAND 09-11-89.','|HEALTH: -HEALTH/ BACHPAN ME SEHAT LAGBHAG THEEK. 10TH PAPRON ME OVARY ME CIST KI SURGERY HUI. LEFT OVERY REMOVE HUI.  |NATURE: SAFAI-SUNDERTA KA KHOOB CRAZE HAI. MIRROR KO BAHUT KAM TIME DETI HAI. SARFA KARNE WALI HAI. KISI KA AHSAN LENA ACHHA NAHI LAGTA. |STUDY: SCHOOL ME 70% SE OOPAR KI VIDYA RAHI. COLLEGE ME MAN NAHI LAGA, BA BEECH ME CHHOD DI. BSC FASHION DESIGNING KI. |CAREER: DUKAN FORN KHOL LO, APNI. FILHAL KISI KI BOUTIQUETTE ME KAM KARTI HAI. (8-JAN-87). VISITED ON 26/8/2017 AND TOLD DUKAN ACHHI CHAL RAHI HAI.  CHILDREN: LEFT OVERY REMOVE HUI HONE SE SANTAN PRAPTI ME KATHINAI AA RAHI HAI. PAHLE ARTIFICIAL ATTEMPT KI THI, SUCCESS NAHI MILI. AB (8/2017) ME DUBARA ATTEMPT KAR RAHI HAI. KEE JAYE.  |MISC: SHURU SE JO BHI CHAHA, KUCH ULAT HI HUA. PARVARISH SUVIDHAJANAK HUI. ','',0,0);
