INSERT INTO tbl_native (serial_no, native_name, gender, gender_code, birth_at, birth_date, birth_date_text, birth_date_legacy, birth_time_legacy, birth_time, birth_time_text, place_id, birth_place, country_name, address_text, remarks, life_spheres, temp_record, is_temporary) VALUES (1265,'NAVPREET KAUR (VIRDI)','F','F',NULL,NULL,'01.11.1970','01.11.1970','07.45','07:45:00','07.45',NULL,'GURDASPUR','INDIA','COMES FROM ZIRAKPUR','|HEALTH: MENTAL AILMENT/ DEPRESSION MEN HAI/ MIGRANE, STOMACH, ENT AILMENT/ SINUS |CAREER: WORKING IN A COMPANY DEALING WITH REAL ESTATE & TRADING, COMPANY PAR CBI KA CHHAPA PADA THA, AB ZAYADA ACHHA NAHI RAHI  |MARRIAGE: DOM=7-11-2004, DIVORCE = MAR-2010 KISI LADKE KO PASAND NAHIN KARTI THI, PCS JAISE KAI RISHTE AAYE THE. VIDESHI LADKE SE VIVAH HUA 2009 KE KARIB. HUSBAND VIDESH BHAG GAYA, VAPIS NAHIN AAYA, INDIAN SHADI HO GAI, USKE BAD COURTMARRIAGE KE LIYE COURT MEN WAIT KARTI RAH GAI, HUSBAND AAYA HI NAHIN.  RUPINDER SINGH 48 YR (2015) KE SATH VIVAH KI BAT CHAL RAHI HAI, USKA DIVORCE HO RAHA HAI.  |MISC: ASHUBH YOG:   NEECH=3 , 4GRAHI=1, RAHU=5, NEECH SHANI=7, MANGAL=12,   CHANDI KA KADA PAHNA HAI LIKING: RED, ORANGE.  MUTER, GOBHI, GHEEYA NOT LIKED, GHAR SE BAHAR KA KHANA ACHHA LAGTA HAI VISITED ON 17-6-2016, ADVISED BABA DEEP JI SHAHID KI YATRA 26.2.2017, 5-TIRATHON KE JAL KA GHAR ME CHHINTA DENA AUR SNAAN KARNA,   PREDICTION: 2017 KA ANT YA 2018 KE MADHYA ME TO VIVAH HOGA HI.  |PALM: THUMB OPENING 90, BRAIN LINE WITH SPACE FROM LIFE LINE, ENDING TOWARDS LUNA, SLIGHTLY FORKED HEART LINE BETWEEN 1ST/2ND FINGERS ML FORKED, ONE BRANCH CURVED DOWN, UPTO HEART LINE FL FAINT, SLIGHTLY FROM LUNA. RING OF JUPITER            ','',1,1);
