INSERT INTO tbl_native (serial_no, native_name, gender, gender_code, birth_at, birth_date, birth_date_text, birth_date_legacy, birth_time_legacy, birth_time, birth_time_text, place_id, birth_place, country_name, address_text, remarks, life_spheres, temp_record, is_temporary) VALUES (1861,'HARJINDER SINGH GHUMAN','M','M',NULL,NULL,'11.10.1952','11.10.1952','23.59','23:59:00','23.59',NULL,'GURDASPUR','INDIA','GHOMAN PANDORI (GHOMAN POST OFFICE, PANDORI VILLAGE), VISITED ON 24.6.2018 (3RD TIME)','|NATURE: OVER SMART, BESHARAM, DHEETH SHAYAD SAALI SE SAMBANDH BANANA CHAHTA HAI. WOH GHAAS NAHI DAAL RAHI. DEC-18 TAK BAAT BAN SAKTI HAI.  |CAREER: JOINED IRRIGATION DEPTT IN 6/6/1978, REMAINDER ABSCONDER FOR 6 MONTHS, PURCHASED AGRICULTURE LAND IN UP. AGAIN CAME BACK AND JOINED DEPTT.   3 KILLE ZAMIN, WOH NAHI BIK SAKTI. HOUSE BECHNA CHAHTA HAI, WOH BIK JAAYEGA.  |MARRIAGE: 16/11/1981 ME VIVAH HUA.  ISKE SASURAL WALON NE UP LADKI BHEJNE SE INKAR KAR DIYA THA, MANGNI TODNE KI BAAT KI THI. VAPIS AA GAYA AUR MARRIAGE HO GAYI. WIFE BAHUT ACHHI HAI.   |CHILDREN: 2 BETIYAN AUR 1 BETA HAI, SABHI AUSTRALIA ME HAIN.  |MISC: WIFE KI SEHAT KE LIYE KILO GHEE BABA DEEP SINGH SHAHEED JI KE JOT ME PAA KE AAO. CHARANJIT BETE KI AULAD NAHI HAI, UPAY KE LIYE MANGLIK SHAANTI KEE JAYEGI. DONON MANGLIK HONE SE SANTAN SUKH ME KAMI HAI.','',1,1);
