INSERT INTO tbl_native (serial_no, native_name, gender, gender_code, birth_at, birth_date, birth_date_text, birth_date_legacy, birth_time_legacy, birth_time, birth_time_text, place_id, birth_place, country_name, address_text, remarks, life_spheres, temp_record, is_temporary) VALUES (1892,'BHARAT KUMAR','M','M',NULL,NULL,'15.11.1978','15.11.1978','20.13','20:13:00','20.13',NULL,'PATIALA','INDIA','C/O SANJEEV BHARDWAJ, MANDIR KALI DEVI WALE.    FEE 500 FIRST TIME, SUBSEQUENT TIME 300','|NATURE: VISITED 2ND TIME, AFTER DURATION OF ONE YEAR.  BATAYA KE JAB AANE KI TAIYARI THI TO THUMB WALL SE JOR SE TAKRAYA AUR DUKH RAHA HAI, SCOOTER ME PETROL KHATAM HO GAYA, RUKA NAHI, AA HI GAYA. PHIR BATAYA RUKAVAT AANE PAR AUR BHI JAYADA ACTION ME AA JAATA HOON.  KUCHH VAHAMI SWABHAV HAI. MAINE CHHANDI KA KADA DAALA HAI, THEEK HAI?  DIAMOND RING DAALI HAI? GALE ME RUDRAKSH KI MAALA DAALI HAI, KAYA THEEK HAIN?  BOL-BHADAAK HAI. BAL-CHHAL ZAYADA NAHI HAI. SANJU BHARDWAJ KA CHELA RAHA HAI. MAAR-KUTAI WALA RAHA HAI  |CAREER: COURTS ME 2013 SE ADVOCATE HAI. GRAHAK PAISE MAAR LETE HAIN. CASE JEET JAANE KE BAAD BHI BOL DETE HAIN KI AAPKE ACCOUNT ME DAAL DENGE.  |BROTHER: ONLY TWO BROTHERS IN ALL.  BROTHER IS B.TECH, MBA, RESIGNED FROM 50,000 PER MONTH SALARY SERVICE, NOW DOING NOTHING SINCE 2016. FATHER INFLUENCED BY BROTHER AND PLAN THAT PARENTAL PROPERTY WORTH 30 KILLA BE SOLD AND A BUSINESS BE STARTED. NATIVE FEEL THAT BROTHER IS UNABLE TO RUN SUCCESSFUL BUSINESS. IN AN PREVIOUS ATTEMPT, HE SOLD 3 KILLAS AND WASTED IN AN BUSINESS.  |PALM:  THUMB OPENING,  LIFE LINE = CLEARLY OVER JUP. FATE LINE = RISING FROM LUNA, STOPPED BY HEART LINE TRAVEL LINE = SHORT BUT FINE BRAIN LINE = LONG, STARTS WITH SPACE FROM LIFE LINE AND ENDS TOWARDS LUNA HEART LINE = NORMAL ENDING BETWEEN 1ST AND 2ND FINGERS   MISC: SR. PITRON KI PIND DAAN KIYA JAAYE.       ','',1,1);
