INSERT INTO tbl_native (serial_no, native_name, gender, gender_code, birth_at, birth_date, birth_date_text, birth_date_legacy, birth_time_legacy, birth_time, birth_time_text, place_id, birth_place, country_name, address_text, remarks, life_spheres, temp_record, is_temporary) VALUES (3303,'SHAKUL VERMA SHUNTY','M','M',NULL,NULL,'19.06.1983','19.06.1983','11.15','11:15:00','11.15',NULL,'RAJPURA','INDIA','M-96469-46042.  S/O SURESH CHAND VERMA (GANDA) SABZI COMMISSION AGENT OF RAJPURA & MOTHER PREM LATA, ','|HEALTH: JANAM SE 2-3 DIN ME SEVERE PILIYA HUA. BLOOD TRANSFUSION HONA THA, JAISE KAISE TAL GAYA. KHANSI KI MEDICINE PHENERGAN RAT KO DI, SAVERE MUNH PHUL GAYA. DHIRE DHIRE SARI DEH ALLERGY SE PHUL GAI, (SKIN TROUBLE), PENIS GAL GAYA THA. BADI UMAR ME BHI JAANGHON ME KHAZ KI TAKLIF RAHI. SINUS KA PAKKA PATIENT HAI. CHHOTI UMAR ME CYCLE SEEKHTE TIME GIR GAYA. DANT TUT KAR GIR GAYA, DOCTOR NE KAHA KE DANT DHOOND KAR LAO,  DOCTOR NE DANT ZOR SE DABA KAR FIT KAR DIYA, AJ BHI DANT LAGA JUDA HAI, KUCH KALA HAI.   |NATURE: DE-ADDICTION CENTRE/ NASHA MUKTI KENDER BAHADURGARH MEN 24/10/2014 SE  (5/2015) ADMIT CHAL RAHA HAI. NALAYAK,   BACHPAN ME BHIKHARI KA ROLE KIYA, INAAM MILA THA. TEACHER NE COMPLIMENT DIYA THA KE CLASS ME JEE LAGATA HAI EMOTIONAL BAHUT HAI, MATA VIDESH SE VAPIS AAI TO JAFFI PAA KE ROYA. ACCIDENT HUYE GIRE PADE COUSIN KO SAMBHALA, AUR KISI ACCIDENT HUYE GIRE PADE RELATIVE KO BHI SAMBHALA.   |STUDY: -STUDY/ 9TH CLASS ME FAIL HO JANE SE SCHOOL BADLA. VAHAN NASHEDI STUDENTS KI SANGTI HO GAYI  |CAREER: UNEMPLOYED, BADA BHAI AUSTRALIA MEN SETTLE HAI. BULAYA THA. ISKA CASE 5/2015 MEN REJECT HO GAYA HAI. BHAI AB BHI BULA RAHA HAI, 7.5 BAND LEKAR IELT PASS KARO, PHIR AAO. RAILWAY COUNTER KI SOCH RAHA HAI, CIRCULATION MONEY KE EK LAKH KA PARBANDH NAHI HO RAHA.    |MARRIAGE: 1ST DIVORCE, 2ND WIFE SUNITA - HARMONIOUS. |CHILDREN: 2 SONS  |MOTHER: PREM LATA, 6-AUG-1980 KO MATA KA VIVAH HUA. LAGBHAG 2000 SE THYROID HAI. 19-FEB-2015 KO PILES KI SURGERY KE LIYE ADMIT HONA THA, MERE PAS AA GAYI. MANSA DEVI YATRA BATAI, SURGERY TAL GAYI.   VISIT 19-JAN-2017, DUBARA PILES KI SURGERY KI NAUBAT HAI, KAYA KIYA JAYE?  AUSTRALIA NOONH KI DELIVERY KARVANE GAYI THI, 29/5/2016 KO HBP KA PATA CHALA. MEDICINE SE PET KHARAB HUA. ACHANAK PILES KA BLOOD AAYA. GALTI SE MEDICINE ZAYADA LE LI, PET KA KABADA HO GAYA.  |FATHER: SABZI MANDI KA ADHATI HAI, KHANDANI ZAMIN BAHUT THI. JUARI HONE SE SAB KUCH LUTA DIYA HAI, LUTA RAHA HAI. GHAR-GHAT KI KOI FIKAR NAHI  |MISC: BIRTH TIME SHAKKI HAI. 11HR TO 13 HR HAI. ISKI MASI NE BATAYA KE 12.45 HR HAI.  ELDER BROTHER RAVI KANT IN MELB.AUSTRALIA AS PR, HIS WIFE IS JYOTI FROM BELOW AVERAGE FAMILY PARENTS BAHUT DUKHI HAIN','',0,0);
